// Additive bindings for separately recovered source-only photo bytes. A registry
// contains no grades; the actual image reader must still verify the image bytes.
import {createHash} from 'node:crypto';
const sha=x=>createHash('sha256').update(x).digest('hex'),hex=x=>typeof x==='string'&&/^[a-f0-9]{64}$/.test(x),clock=x=>x===null||typeof x==='string'&&/(Z|[+-]\d\d:\d\d)$/.test(x)&&Number.isFinite(Date.parse(x));
function validate(registry){if(!registry||registry.version!==1||!hex(registry.generation)||!Array.isArray(registry.entries)||registry.entries.length>100000)throw Error('Invalid recovered photo registry');const seen=new Set();for(const e of registry.entries){if(!e||typeof e.recordKey!=='string'||!/^\d{4}-\d{2}-\d{2}\/.+/.test(e.recordKey)||e.recordKey.length>256||seen.has(e.recordKey)||!hex(e.sourceRowSha256)||!hex(e.urlSha256)||!hex(e.imageSha256)||!hex(e.objectSha256)||!clock(e.proofTimestamp)||typeof e.observedAt!=='string'||!Number.isFinite(Date.parse(e.observedAt)))throw Error('Invalid recovered photo binding');seen.add(e.recordKey)}return registry}
export function applyRecoveredPhotoBindings(rows,registry){if(!Array.isArray(rows))throw Error('Invalid photo rows');if(registry===null)return rows;validate(registry);const by=new Map(registry.entries.map(x=>[x.recordKey,x]));return rows.map(row=>{const e=by.get(row.key),d=row.delivery||{},p=row.photo||{};if(!e||row.sourceOnly?.assessmentState!=='unavailable'||row.key!==row.date+'/'+d.delivery_id||d.source_sha256!==e.sourceRowSha256||typeof d.photo_url!=='string'||!d.photo_url||sha(d.photo_url)!==e.urlSha256||(Object.hasOwn(d,'raw_upload')?d.raw_upload:d.upload??null)!==e.proofTimestamp||d.photo_sha256!=null||p.grade!=null||p.reviewStatus==='reviewed'||p.staleReview)return row;return {...row,delivery:{...d,photo_sha256:e.imageSha256}}})}
export async function loadRecoveredPhotoBindings(repository){const p=repository?.publication?.recoveredPhotoBindings;if(!p)return null;if(p.version!==1||!hex(p.sha256)||p.path!=='recovered-photo-bindings/'+p.sha256+'.json'||typeof repository.readFile!=='function')throw Error('Invalid recovered photo registry pointer');const bytes=await repository.readFile('state',p.path,{maxBytes:16*1024*1024});if(!Buffer.isBuffer(bytes)||sha(bytes)!==p.sha256)throw Error('Recovered photo registry integrity failure');return validate(JSON.parse(bytes))}
